/**
 * A contact as seen by the iOS UI.
 */
public struct FfiContact {
    public var jid: String
    public var displayName: String
    /**
     * "online" | "offline" | "away"
     */
    public var status: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(jid: String, displayName: String, 
        /**
         * "online" | "offline" | "away"
         */status: String) {
        self.jid = jid
        self.displayName = displayName
        self.status = status
    }
}

#if compiler(>=6)
extension FfiContact: Sendable {}
#endif


extension FfiContact: Equatable, Hashable {
    public static func ==(lhs: FfiContact, rhs: FfiContact) -> Bool {
        if lhs.jid != rhs.jid {
            return false
        }
        if lhs.displayName != rhs.displayName {
            return false
        }
        if lhs.status != rhs.status {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(jid)
        hasher.combine(displayName)
        hasher.combine(status)
    }
}



