/**
 * A chat message as seen by the iOS UI.
 */
public struct FfiMessage {
    public var id: String
    public var fromJid: String
    public var toJid: String
    public var body: String
    /**
     * Unix timestamp (seconds since epoch)
     */
    public var timestamp: Int64
    public var isEncrypted: Bool
    /**
     * "sent" | "delivered" | "read" | "failed"
     */
    public var status: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, fromJid: String, toJid: String, body: String, 
        /**
         * Unix timestamp (seconds since epoch)
         */timestamp: Int64, isEncrypted: Bool, 
        /**
         * "sent" | "delivered" | "read" | "failed"
         */status: String) {
        self.id = id
        self.fromJid = fromJid
        self.toJid = toJid
        self.body = body
        self.timestamp = timestamp
        self.isEncrypted = isEncrypted
        self.status = status
    }
}

#if compiler(>=6)
extension FfiMessage: Sendable {}
#endif


extension FfiMessage: Equatable, Hashable {
    public static func ==(lhs: FfiMessage, rhs: FfiMessage) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.fromJid != rhs.fromJid {
            return false
        }
        if lhs.toJid != rhs.toJid {
            return false
        }
        if lhs.body != rhs.body {
            return false
        }
        if lhs.timestamp != rhs.timestamp {
            return false
        }
        if lhs.isEncrypted != rhs.isEncrypted {
            return false
        }
        if lhs.status != rhs.status {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(fromJid)
        hasher.combine(toJid)
        hasher.combine(body)
        hasher.combine(timestamp)
        hasher.combine(isEncrypted)
        hasher.combine(status)
    }
}



