public enum FfiError: Swift.Error {

    
    
    case NotConnected
    case Connection(reason: String
    )
    case Omemo(reason: String
    )
    case Send(reason: String
    )
    case Roster(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotConnected
        case 2: return .Connection(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Omemo(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Send(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Roster(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotConnected:
            writeInt(&buf, Int32(1))
        
        
        case let .Connection(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Omemo(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Send(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Roster(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


